"""World and schematic export, read back with the independent reader in mcread.py."""

import gzip
import io

import nbtlib
import pytest

from mcread import block_at, read_region, surface, unpack
from schemacraft.anvil import DATA_VERSION, write_world
from schemacraft.blocks import BASE_Y, GROUND_Y, build
from schemacraft.introspect import introspect
from schemacraft.layout import layout
from schemacraft.schem import write_schem

# top-level chunk tags of a world generated by Arnis for 1.21.4, which Minecraft opens
ARNIS_CHUNK_KEYS = {
    "DataVersion", "xPos", "zPos", "yPos", "Status", "LastUpdate", "InhabitedTime", "isLightOn",
    "sections", "block_entities", "Heightmaps", "structures", "PostProcessing", "block_ticks", "fluid_ticks",
}


def make(url, tmp_path, name):
    model = introspect(url)
    city = layout(model)
    blocks, spawn = build(model, city, name)
    world = write_world(blocks, tmp_path / name, name, spawn)
    chunks = {}
    for region in (world / "region").glob("*.mca"):
        chunks.update(read_region(region))
    return model, city, blocks, spawn, world, chunks


@pytest.fixture(scope="module")
def chinook(chinook_url, tmp_path_factory):
    return make(chinook_url, tmp_path_factory.mktemp("w"), "Chinook")


@pytest.fixture(scope="module")
def library(library_url, tmp_path_factory):
    return make(library_url, tmp_path_factory.mktemp("w"), "Library")


def signs(chunks):
    return [e for c in chunks.values() for e in c["block_entities"]]


def sign_text(e):
    return " ".join(str(m) for m in e["front_text"]["messages"])


def test_level_dat(chinook):
    *_, spawn, world, _ = chinook
    data = nbtlib.load(world / "level.dat")["Data"]
    assert data["DataVersion"] == DATA_VERSION and data["Version"]["Name"] == "1.21.4"
    assert data["LevelName"] == "Chinook" and data["GameType"] == 1 and data["allowCommands"] == 1
    gen = data["WorldGenSettings"]["dimensions"]["minecraft:overworld"]["generator"]
    assert gen["type"] == "minecraft:flat"
    assert [str(l["block"]) for l in gen["settings"]["layers"]] == [
        "minecraft:bedrock", "minecraft:dirt", "minecraft:grass_block"]
    assert set(data["WorldGenSettings"]["dimensions"]) == {
        "minecraft:overworld", "minecraft:the_nether", "minecraft:the_end"}
    assert (data["SpawnX"], data["SpawnY"], data["SpawnZ"]) == spawn


def test_chunks_have_the_tags_minecraft_expects(chinook):
    chunks = chinook[-1]
    for chunk in chunks.values():
        assert set(chunk) == ARNIS_CHUNK_KEYS
        assert chunk["DataVersion"] == DATA_VERSION and chunk["Status"] == "minecraft:full"
        assert [int(s["Y"]) for s in chunk["sections"]] == list(range(-4, 20))
        assert surface(chunk) == unpack(chunk["Heightmaps"]["WORLD_SURFACE"], 9, 256)


def test_superflat_ground_matches_the_generator(chinook):
    chunks = chinook[-1]
    for cx, cz in chunks:
        x, z = cx * 16 + 7, cz * 16 + 7
        assert block_at(chunks, x, -64, z) == "minecraft:bedrock"
        assert block_at(chunks, x, -63, z) == block_at(chunks, x, -62, z) == "minecraft:dirt"


def test_buildings(chinook):
    model, city, _, _, _, chunks = chinook
    columns = {t["name"]: len(t["columns"]) for t in model["tables"]}
    for b in city["buildings"]:
        x0, z0, x1, z1 = b["x"], b["z"], b["x"] + b["w"] - 1, b["z"] + b["d"] - 1
        top = BASE_Y + b["h"] - 1
        assert block_at(chunks, x0, BASE_Y, z0) in ("minecraft:stone_bricks", "minecraft:cracked_stone_bricks")
        assert block_at(chunks, x1, top, z1).endswith("_terracotta")
        assert block_at(chunks, x1, top + 1, z1) == "minecraft:air"
        assert block_at(chunks, x0 + 1, BASE_Y, z0 + 1) == "minecraft:ladder"
        assert block_at(chunks, x0, GROUND_Y, z0) == "minecraft:polished_andesite"

        inside = [e for e in signs(chunks) if x0 < e["x"] < x1 and z0 < e["z"] < z1]
        assert len(inside) == columns[b["table"]], b["table"]
        outside = [e for e in signs(chunks) if b["table"] in sign_text(e) and not (x0 <= e["x"] <= x1 and z0 <= e["z"] <= z1)]
        assert outside, f"{b['table']} has no name sign at its door"


def test_doors_open_onto_roads(chinook):
    _, city, _, _, _, chunks = chinook
    buildings = {b["table"]: b for b in city["buildings"]}
    for road in city["roads"]:
        for table, (x, z) in ((road["from"], road["cells"][0]), (road["to"], road["cells"][-1])):
            b = buildings[table]
            # step from the road end into the wall: the opening is two blocks high
            wx = min(max(x, b["x"]), b["x"] + b["w"] - 1)
            wz = min(max(z, b["z"]), b["z"] + b["d"] - 1)
            if (wx, wz) in {(b["x"], b["z"]), (b["x"] + b["w"] - 1, b["z"]), (b["x"], b["z"] + b["d"] - 1),
                            (b["x"] + b["w"] - 1, b["z"] + b["d"] - 1)}:
                continue  # corner: the door was moved one block along the wall
            assert block_at(chunks, wx, BASE_Y, wz) == "minecraft:air", (table, wx, wz)
            assert block_at(chunks, wx, BASE_Y + 1, wz) == "minecraft:air"


def test_roads_and_lamps(chinook):
    _, city, _, spawn, _, chunks = chinook
    for road in city["roads"]:
        for x, z in road["cells"]:
            assert block_at(chunks, x, GROUND_Y, z) == "minecraft:polished_andesite"
            assert block_at(chunks, x, BASE_Y, z) == "minecraft:air"
    blocks = {block_at(chunks, x, BASE_Y + 1, z) for road in city["roads"] for x0, z0 in road["cells"]
              for x, z in ((x0 + 1, z0), (x0 - 1, z0), (x0, z0 + 1), (x0, z0 - 1))}
    assert "minecraft:lantern" in blocks
    x, y, z = spawn
    assert block_at(chunks, x, y, z) == "minecraft:air" and block_at(chunks, x, y + 1, z) == "minecraft:air"


def test_data_quality_is_visible(library):
    model, city, _, _, _, chunks = library
    unindexed = next(r for r in city["roads"] if (r["from"], r["to"]) == ("book", "author"))
    indexed = {tuple(c) for r in city["roads"] if r["indexed"] for c in r["cells"]}
    dark = [c for c in unindexed["cells"] if tuple(c) not in indexed]
    assert dark and all(block_at(chunks, x, GROUND_Y, z) == "minecraft:blackstone" for x, z in dark)

    walls = {}
    for b in city["buildings"]:
        walls[b["table"]] = [block_at(chunks, x, y, b["z"]) for x in range(b["x"], b["x"] + b["w"])
                             for y in range(BASE_Y, BASE_Y + b["h"] - 1)]
    assert "minecraft:cracked_stone_bricks" in walls["author"]  # bio is 80 % null
    assert "minecraft:cracked_stone_bricks" not in walls["review"]  # no nulls at all
    assert set(walls["top_books"]) <= {"minecraft:light_blue_stained_glass", "minecraft:air", "minecraft:oak_wall_sign"}


def test_schematic(chinook, tmp_path):
    _, city, blocks, _, _, chunks = chinook
    size = write_schem(blocks, tmp_path / "c.schem")
    with gzip.open(tmp_path / "c.schem") as f:
        schem = nbtlib.File.parse(io.BytesIO(f.read()))
    assert schem.root_name == "Schematic" and schem["Version"] == 2
    w, h, l = (int(schem[k]) for k in ("Width", "Height", "Length"))
    assert (w, h, l) == size

    palette = {int(i): name for name, i in schem["Palette"].items()}
    data = [b & 0xFF for b in schem["BlockData"]]
    ids, i = [], 0
    while i < len(data):  # varint decode
        value, shift = 0, 0
        while True:
            value |= (data[i] & 0x7F) << shift
            i += 1
            if not data[i - 1] & 0x80:
                break
            shift += 7
        ids.append(value)
    assert len(ids) == w * h * l

    x0, z0, *_ = blocks.bounds()
    for b in city["buildings"]:
        for x, y, z in ((b["x"], BASE_Y, b["z"]), (b["x"] + 2, GROUND_Y, b["z"] + 2), (b["x"] + 1, BASE_Y + 1, b["z"] + 1)):
            in_schem = palette[ids[(x - x0) + (z - z0) * w + (y - GROUND_Y) * w * l]].split("[")[0]
            assert in_schem == block_at(chunks, x, y, z)
    assert len(schem["BlockEntities"]) == len(signs(chunks))
